contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address asset) public payable {
        require(true);

        // Read-only query on c, observed through try/catch (view call, state unchanged)
        bool distributionReverted;
        try c.getAssetDistributionData(asset) returns (uint256, uint256, uint256) {
            distributionReverted = false;
        } catch {
            distributionReverted = true;
        }

        // Observable state through public getters
        address cfg = c.lrtConfig();
        uint256 maxNdc = c.maxNodeDelegatorCount();
        address[] memory queue = c.getNodeDelegatorQueue();

        // General rule: the distribution query succeeds only when a non-zero lrtConfig
        // is configured (and then the queue never exceeds the max node delegator count);
        // otherwise it must revert for every asset.
        assert(
            (distributionReverted && cfg == address(0)) ||
            (!distributionReverted && cfg != address(0) && queue.length <= maxNdc)
        );
    }

    receive() external payable {}
}

