contract InvMutTest {
    C c;
    bytes4 constant RSETH_PRICE_SEL = bytes4(keccak256("getRSETHPrice()"));

    constructor(C _c) { c = _c; }

    function run(address asset, uint256 amount) public {
        require(amount % 2 == 0, "use even amount");
        // point c's config at this test contract; our fallback answers oracle calls
        c.initialize(address(this));
        uint256 mintAmount = c.getRsETHAmountToMint(asset, amount);
        assert(mintAmount == amount / 2);
    }

    fallback(bytes calldata) external returns (bytes memory) {
        // rsETH price = 4, every other config/oracle query returns 2
        if (msg.sig == RSETH_PRICE_SEL) {
            return abi.encode(uint256(4));
        }
        return abi.encode(uint256(2));
    }

    receive() external payable {}
}

