    constructor(C _c) { c = _c; }

    function run(address a) public {
        require(a != address(0));
        c.initialize(address(this));
        uint256 beforeLen = c.getNodeDelegatorQueue().length;
        address[] memory arr = new address[](1);
        arr[0] = a;
        c.addNodeDelegatorContractToQueue(arr);
        address[] memory q = c.getNodeDelegatorQueue();
        assert(q.length == beforeLen + 1 && q[q.length - 1] == a);
    }

    fallback(bytes calldata) external payable returns (bytes memory) {
